const ordinary = (vertices, edges) => ({ graphType: "OrdinaryGraph", directed: true, vertices, edges });

export const SSSP_FIXTURES = Object.freeze([
  {
    id: "simple-chain",
    mode: "STATIC",
    graph: ordinary(["C", "A", "B"], [
      { source: "A", target: "B", weight: 1 },
      { source: "B", target: "C", weight: 2 },
    ]),
    source: "A",
    expectedMapping: ["A", "B", "C"],
    expectedCsr: { rowOffsets: [0, 1, 2, 2], columnIndices: [1, 2], weights: [1, 2] },
    expectedDistances: [0, 1, 3],
  },
  {
    id: "diamond-equal-cost",
    mode: "STATIC",
    graph: ordinary(["D", "C", "B", "A"], [
      { source: "A", target: "B", weight: 1 },
      { source: "A", target: "C", weight: 1 },
      { source: "B", target: "D", weight: 1 },
      { source: "C", target: "D", weight: 1 },
    ]),
    source: "A",
    expectedMapping: ["A", "B", "C", "D"],
    expectedCsr: { rowOffsets: [0, 2, 3, 4, 4], columnIndices: [1, 2, 3, 3], weights: [1, 1, 1, 1] },
    expectedDistances: [0, 1, 1, 2],
  },
  {
    id: "disconnected",
    mode: "STATIC",
    graph: ordinary(["A", "B", "C"], [{ source: "A", target: "B", weight: 2 }]),
    source: "A",
    expectedMapping: ["A", "B", "C"],
    expectedCsr: { rowOffsets: [0, 1, 1, 1], columnIndices: [1], weights: [2] },
    expectedDistances: [0, 2, null],
  },
  {
    id: "insertion-decreases-distance",
    mode: "COMPARE",
    graph: ordinary(["A", "B", "C"], [
      { source: "A", target: "B", weight: 5 },
      { source: "B", target: "C", weight: 5 },
    ]),
    source: "A",
    updates: { deletions: [], insertions: [{ source: "A", target: "C", weight: 1 }] },
    expectedMapping: ["A", "B", "C"],
    expectedCsr: { rowOffsets: [0, 1, 2, 2], columnIndices: [1, 2], weights: [5, 5] },
    expectedDistances: [0, 5, 1],
  },
  {
    id: "insertion-no-effect",
    mode: "COMPARE",
    graph: ordinary(["A", "B", "C"], [
      { source: "A", target: "B", weight: 5 },
      { source: "B", target: "C", weight: 5 },
    ]),
    source: "A",
    updates: { deletions: [], insertions: [{ source: "A", target: "C", weight: 20 }] },
    expectedMapping: ["A", "B", "C"],
    expectedCsr: { rowOffsets: [0, 1, 2, 2], columnIndices: [1, 2], weights: [5, 5] },
    expectedDistances: [0, 5, 10],
  },
  {
    id: "deletion-invalidates-parent",
    mode: "COMPARE",
    graph: ordinary(["A", "B", "C"], [
      { source: "A", target: "B", weight: 1 },
      { source: "A", target: "C", weight: 5 },
      { source: "B", target: "C", weight: 1 },
    ]),
    source: "A",
    updates: { deletions: [{ source: "B", target: "C" }], insertions: [] },
    expectedMapping: ["A", "B", "C"],
    expectedCsr: { rowOffsets: [0, 2, 3, 3], columnIndices: [1, 2, 2], weights: [1, 5, 1] },
    expectedDistances: [0, 1, 5],
  },
  {
    id: "deletion-creates-unreachable",
    mode: "COMPARE",
    graph: ordinary(["A", "B", "C"], [
      { source: "A", target: "B", weight: 1 },
      { source: "B", target: "C", weight: 1 },
    ]),
    source: "A",
    updates: { deletions: [{ source: "B", target: "C" }], insertions: [] },
    expectedMapping: ["A", "B", "C"],
    expectedCsr: { rowOffsets: [0, 1, 2, 2], columnIndices: [1, 2], weights: [1, 1] },
    expectedDistances: [0, 1, null],
  },
  {
    id: "mixed-batch",
    mode: "COMPARE",
    graph: ordinary(["A", "B", "C", "D"], [
      { source: "A", target: "B", weight: 5 },
      { source: "A", target: "C", weight: 20 },
      { source: "B", target: "C", weight: 5 },
      { source: "C", target: "D", weight: 1 },
    ]),
    source: "A",
    updates: {
      deletions: [{ source: "A", target: "C" }],
      insertions: [{ source: "A", target: "D", weight: 3 }],
    },
    expectedMapping: ["A", "B", "C", "D"],
    expectedCsr: { rowOffsets: [0, 2, 3, 4, 4], columnIndices: [1, 2, 2, 3], weights: [5, 20, 5, 1] },
    expectedDistances: [0, 5, 10, 3],
  },
  {
    id: "isolated-vertices",
    mode: "STATIC",
    graph: ordinary(["source", "isolated-1", "isolated-2"], []),
    source: "source",
    expectedMapping: ["isolated-1", "isolated-2", "source"],
    expectedCsr: { rowOffsets: [0, 0, 0, 0], columnIndices: [], weights: [] },
    expectedDistances: [null, null, 0],
  },
  {
    id: "zero-weight-cycle",
    mode: "STATIC",
    graph: ordinary(["Z", "A", "B"], [
      { source: "Z", target: "B", weight: 0 },
      { source: "B", target: "A", weight: 0 },
      { source: "A", target: "B", weight: 0 },
    ]),
    source: "Z",
    expectedMapping: ["A", "B", "Z"],
    expectedCsr: { rowOffsets: [0, 1, 2, 3], columnIndices: [1, 0, 1], weights: [0, 0, 0] },
    expectedDistances: [0, 0, 0],
  },
  {
    id: "invalid-negative-weight",
    mode: "STATIC",
    graph: ordinary(["A", "B"], [{ source: "A", target: "B", weight: -1 }]),
    source: "A",
    expectedError: "UNSUPPORTED_WEIGHT_MODEL",
  },
  {
    id: "stale-graph-version",
    mode: "INCREMENTAL",
    graph: ordinary(["A", "B"], [{ source: "A", target: "B", weight: 1 }]),
    source: "A",
    updates: { deletions: [], insertions: [] },
    staleGraphVersion: true,
    expectedMapping: ["A", "B"],
    expectedCsr: { rowOffsets: [0, 1, 1], columnIndices: [1], weights: [1] },
    expectedError: "STALE_GRAPH_VERSION",
  },
]);
